const stoppedAccounts = `-- name: StoppedAccounts :many
SELECT a.id, a.kind FROM account a
LEFT JOIN account o ON o.id = a.owner_id
WHERE a.stopped_at IS NOT NULL OR o.stopped_at IS NOT NULL
`

type StoppedAccountsRow struct {
	ID   pgtype.UUID
	Kind string
}

// The accounts stopped: those stopped themselves, and the machine sailors
// of a human stopped.
func (q *Queries) StoppedAccounts(ctx context.Context) ([]StoppedAccountsRow, error) {
	rows, err := q.db.Query(ctx, stoppedAccounts)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []StoppedAccountsRow
	for rows.Next() {
		var i StoppedAccountsRow
		if err := rows.Scan(&i.ID, &i.Kind); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const takeRecoveryNotice = `-- name: TakeRecoveryNotice :one
UPDATE account a SET recovered_at = NULL
FROM (SELECT o.id, o.recovered_at FROM account o WHERE o.id = $1 FOR UPDATE) old
WHERE a.id = old.id
RETURNING old.recovered_at
`

// When the recovery code was last used, if no sign-in has been told yet;
// telling this one clears it.
func (q *Queries) TakeRecoveryNotice(ctx context.Context, id pgtype.UUID) (pgtype.Timestamptz, error) {
	row := q.db.QueryRow(ctx, takeRecoveryNotice, id)
	var recovered_at pgtype.Timestamptz
	err := row.Scan(&recovered_at)
	return recovered_at, err
}
